<?php
session_start();if(!isset($_SESSION["admin_id"])) {header("Location: login.php");exit;}require "../config/database.php";$id=(int)($_GET["id"]??0);
$s=$conn->prepare("SELECT c.*,u.name,u.email FROM complaints c JOIN users u ON u.id=c.user_id WHERE c.id=?");$s->bind_param("i",$id);$s->execute();$c=$s->get_result()->fetch_assoc();if(!$c)die("Complaint not found.");
if($_SERVER["REQUEST_METHOD"]==="POST"){ $status=$_POST["status"]; $remark=trim($_POST["remark"]);$s=$conn->prepare("UPDATE complaints SET status=?,admin_remark=?,updated_at=NOW() WHERE id=?");$s->bind_param("ssi",$status,$remark,$id);$s->execute();header("Location: dashboard.php");exit;}
?>
